# دالة Debounce في TypeScript

## التنفيذ الأساسي

```typescript
function debounce<T extends (...args: unknown[]) => unknown>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  return function (...args: Parameters<T>): void {
    // إلغاء المؤقت السابق إن وجد
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // إنشاء مؤقت جديد
    timeoutId = setTimeout(() => {
      fn(...args);
      timeoutId = null;
    }, delay);
  };
}
```

---

## نسخة متقدمة مع خيارات إضافية

```typescript
interface DebounceOptions {
  leading?: boolean;  // تنفيذ فوري عند أول استدعاء
  trailing?: boolean; // تنفيذ بعد انتهاء الانتظار (افتراضي)
  maxWait?: number;   // أقصى وقت انتظار قبل التنفيذ الإجباري
}

interface DebouncedFunction<T extends (...args: unknown[]) => unknown> {
  (...args: Parameters<T>): ReturnType<T> | undefined;
  cancel: () => void;   // إلغاء التنفيذ المعلق
  flush: () => ReturnType<T> | undefined; // تنفيذ فوري
  isPending: () => boolean; // هل يوجد تنفيذ معلق؟
}

function debounce<T extends (...args: unknown[]) => unknown>(
  fn: T,
  delay: number,
  options: DebounceOptions = {}
): DebouncedFunction<T> {
  const { leading = false, trailing = true, maxWait } = options;

  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let maxTimeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<T> | null = null;
  let lastResult: ReturnType<T> | undefined;
  let lastCallTime: number | null = null;

  // تنفيذ الدالة الأصلية
  const invoke = (): ReturnType<T> | undefined => {
    if (lastArgs !== null) {
      lastResult = fn(...lastArgs) as ReturnType<T>;
      lastArgs = null;
    }
    return lastResult;
  };

  // تنظيف جميع المؤقتات
  const clearTimers = (): void => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (maxTimeoutId !== null) {
      clearTimeout(maxTimeoutId);
      maxTimeoutId = null;
    }
  };

  const debouncedFn = function (
    ...args: Parameters<T>
  ): ReturnType<T> | undefined {
    lastArgs = args;
    lastCallTime = Date.now();

    const shouldCallLeading = leading && timeoutId === null;

    // إعادة ضبط المؤقت الرئيسي
    if (timeoutId !== null) clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && lastArgs !== null) {
        invoke();
      }
      clearTimers();
    }, delay);

    // ضبط مؤقت maxWait
    if (maxWait !== undefined && maxTimeoutId === null) {
      maxTimeoutId = setTimeout(() => {
        maxTimeoutId = null;
        if (lastArgs !== null) invoke();
      }, maxWait);
    }

    // تنفيذ فوري عند leading
    if (shouldCallLeading) {
      return invoke();
    }

    return lastResult;
  };

  // إلغاء التنفيذ المعلق
  debouncedFn.cancel = (): void => {
    clearTimers();
    lastArgs = null;
    lastCallTime = null;
  };

  // تنفيذ فوري
  debouncedFn.flush = (): ReturnType<T> | undefined => {
    clearTimers();
    return invoke();
  };

  // التحقق من وجود تنفيذ معلق
  debouncedFn.isPending = (): boolean => timeoutId !== null;

  return debouncedFn;
}
```

---

## أمثلة الاستخدام

```typescript
// ✅ مثال 1: البحث الفوري
const handleSearch = debounce((query: string) => {
  console.log(`🔍 جاري البحث عن: ${query}`);
  // استدعاء API...
}, 500);

// سيتم تنفيذ البحث مرة واحدة فقط بعد 500ms
handleSearch("TypeScript");
handleSearch("TypeScript d");
handleSearch("TypeScript debounce"); // ← هذا فقط سيُنفَّذ


// ✅ مثال 2: حفظ تلقائي مع maxWait
const autoSave = debounce(
  (content: string) => {
    console.log(`💾 جاري الحفظ...`);
  },
  1000,
  { maxWait: 5000 } // حفظ إجباري كل 5 ثوانٍ على الأقل
);


// ✅ مثال 3: تنفيذ فوري (leading)
const handleButtonClick = debounce(
  () => console.log("🖱️ تم الضغط!"),
  300,
  { leading: true, trailing: false }
);


// ✅ مثال 4: استخدام cancel و flush
const debouncedUpdate = debounce((value: number) => {
  console.log(`📊 القيمة: ${value}`);
}, 1000);

debouncedUpdate(42);

// إلغاء التنفيذ
debouncedUpdate.cancel();

// أو تنفيذ فوري
debouncedUpdate.flush();

// التحقق من وجود تنفيذ معلق
console.log(debouncedUpdate.isPending()); // false
```

---

## مقارنة سريعة

| الخيار | الوصف | متى تستخدمه؟ |
|--------|-------|--------------|
| `trailing` ✅ | ينفذ بعد انتهاء الانتظار | البحث، التحقق من النماذج |
| `leading` | ينفذ فور الاستدعاء الأول | أزرار الإرسال، النقرات |
| `maxWait` | حد أقصى للانتظار | الحفظ التلقائي |
